  ('93c149b6-1b7d-5f33-a482-58ec85e9a2bb', null, (select id from public.skills where slug = 'read-g11-argument-evidence'), null, 'medium',
   $q$Which of Pollock's claims does the passage identify as unsupported?$q$, $q$[{"text":"That following the neighbors was no substitute for counting costs.","is_correct":false,"misconception_token":"misjudges-evidence"},{"text":"That a railroad would frighten livestock and ruin farms.","is_correct":true},{"text":"That canal shipping would cost half as much as rail.","is_correct":false,"misconception_token":"misjudges-evidence"},{"text":"That canals had proven themselves over two decades.","is_correct":false,"misconception_token":"misjudges-evidence"}]$q$::jsonb, $q$That a railroad would frighten livestock and ruin farms.$q$, $q$The passage says Pollock made the livestock claim "though he offered no examples of this happening anywhere." The cost claim was backed by the company's own estimates, which even his opponents did not dispute.$q$, 'draft', '4a94ef71-c422-5acd-9e2a-57dc871d959e')
